    colors = [v for v in sorted({x for row in grid for x in row}) if v != bg]
    bars = {c: [] for c in colors}
    for r, row in enumerate(grid):
        c = 0
        while c < len(row):
            if row[c] != bg:
                color = row[c]
                j = c
                while j < len(row) and row[j] == color:
                    j += 1
                bars[color].append((r, c, j-c))
                c = j
            else:
                c += 1
    if len(colors) != 2:
        raise ValueError('expected two foreground colors')
    # Encode the relative placement of the two kinds of horizontal bars as a 2x3 motif.
    # Determine each color's horizontal extent across its observed runs; divide into
    # left/center/right bins and mark which bins contain the color.
    all_runs = [item for arr in bars.values() for item in arr]
    left = min(c for _, c, _ in all_runs)
    right = max(c+n-1 for _, c, n in all_runs)
    width = right-left+1
    out = [[0]*3 for _ in range(2)]
    for ri, color in enumerate(colors):
        for _, c, n in bars[color]:
            mid = c + (n-1)//2
            col = min(2, (3*(mid-left))//width)
            out[ri][col] = color
    return out

