                if row[c] == color:
                    runs += 1
                    while c < len(row) and row[c] == color:
                        c += 1
                else:
                    c += 1
        tokens.extend([color] * runs)
    if len(tokens) > 6:
        raise ValueError('more than six bars')
    output = [[0, 0, 0], [0, 0, 0]]
